public class LongestCommonSubsequence { public static string CalculateLCS(string str1, string str2) { int[,] dp = new int[str1.Length + 1, str2.Length + 1]; for (int i = 1; i <= str1.Length; i++) { for (int j = 1; j <= str2.Length; j++) { if (str1[i - 1] == str2[j - 1]) { dp[i, j] = dp[i - 1, j - 1] + 1; } else { dp[i, j] = Math.Max(dp[i - 1, j], dp[i, j - 1]); } } } return GetLCS(str1, str2, dp); } private static string GetLCS(string str1, string str2, int[,] dp) { string lcs = string.Empty; int i = str1.Length, j = str2.Length; while (i > 0 && j > 0) { if (str1[i - 1] == str2[j - 1]) { lcs = str1[i - 1] + lcs; i--; j--; } else if (dp[i - 1, j] > dp[i, j - 1]) { i--; } else { j--; } } return lcs; } }